-- Detection identity keys (coverage spec §3, §4, §10).
--
-- One row per (detection, key type, key value). Values are GENERATED BY THE
-- SHIPPED MODULE `_shared/detection-identity.ts` and inserted by
-- scripts/identity/backfill-detection-identity.ts -- never computed here.
-- Reimplementing normalisation in SQL is the drift that produced D3/E2/E4.
--
-- Every lifecycle participates. There is deliberately no filter on
-- library_type, promotion_status, review_status or status: those are badges,
-- not relevance gates (spec §1, §7). The gate that excluded them passed 0 of
-- 11,820 detections.
--
-- Filename note: this file is deliberately NOT named `..._detection_identity_keys.sql`.
-- The repo's local pre-commit hook feeds shell globs to `grep -E`, so its
-- `*.key` entry reduces to `.key` and false-matches the substring `_key` in any
-- ordinary filename. The applied migration version (20260812090000) is
-- unchanged; only the descriptive suffix differs.

CREATE TABLE IF NOT EXISTS public.detection_identity_keys (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  detection_id  text NOT NULL REFERENCES public.detections(id) ON DELETE CASCADE,
  key_type      text NOT NULL CHECK (key_type IN ('external_id', 'fingerprint', 'locator', 'title')),
  -- Namespace is required for external_id (spec §4: shape alone is not
  -- validity) and meaningless for the others.
  namespace     text,
  key_value     text NOT NULL CHECK (length(btrim(key_value)) > 0),
  created_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT detection_identity_keys_unique UNIQUE (detection_id, key_type, key_value),
  CONSTRAINT detection_identity_keys_namespace_required
    CHECK ((key_type = 'external_id') = (namespace IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_detection_identity_keys_lookup
  ON public.detection_identity_keys (key_type, key_value);
CREATE INDEX IF NOT EXISTS idx_detection_identity_keys_detection
  ON public.detection_identity_keys (detection_id);

ALTER TABLE public.detection_identity_keys ENABLE ROW LEVEL SECURITY;

-- Identity keys are derived from detections the caller can already see. The
-- policy mirrors hybrid_search_detections' visibility rule so a private rule is
-- excluded without leaking its existence (spec §9).
DROP POLICY IF EXISTS detection_identity_keys_select ON public.detection_identity_keys;
CREATE POLICY detection_identity_keys_select ON public.detection_identity_keys
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM public.detections d
      WHERE d.id = detection_identity_keys.detection_id
        AND (
          d.library_type = 'production'
          OR (d.library_type = 'development' AND (d.visibility = 'shared' OR d.user_id = auth.uid()))
        )
    )
  );

-- Ambiguity is DERIVED, never enumerated. A key group is ambiguous when the
-- rows sharing it cannot be reconciled as copies of one rule:
--   * they are claimed by different namespaces -- two vendors asserting the
--     same identifier means the identifier identifies nothing (this is what a
--     reused placeholder UUID looks like in the data); or
--   * they agree on neither their normalized title nor their query
--     fingerprint. A renamed copy still shares a fingerprint; a reformatted
--     copy still shares a title. Sharing neither is not a copy.
CREATE OR REPLACE VIEW public.detection_identity_resolution AS
WITH grouped AS (
  SELECT
    k.key_type,
    k.key_value,
    count(DISTINCT k.detection_id)                                     AS copies,
    count(DISTINCT k.namespace)                                        AS namespaces,
    min(k.namespace)                                                   AS namespace,
    count(DISTINCT t.key_value)                                        AS distinct_titles,
    count(DISTINCT f.key_value)                                        AS distinct_fingerprints,
    array_agg(DISTINCT k.detection_id)                                 AS detection_ids
  FROM public.detection_identity_keys k
  LEFT JOIN public.detection_identity_keys t
    ON t.detection_id = k.detection_id AND t.key_type = 'title'
  LEFT JOIN public.detection_identity_keys f
    ON f.detection_id = k.detection_id AND f.key_type = 'fingerprint'
  GROUP BY k.key_type, k.key_value
)
SELECT
  key_type,
  namespace,
  key_value,
  copies,
  detection_ids,
  CASE
    WHEN copies = 1 THEN 'valid'
    WHEN namespaces > 1 THEN 'ambiguous'
    WHEN distinct_titles <= 1 OR distinct_fingerprints <= 1 THEN 'valid'
    ELSE 'ambiguous'
  END AS status
FROM grouped;

COMMENT ON VIEW public.detection_identity_resolution IS
  'Whether each identity key group resolves to one logical detection. Derived, not enumerated -- see coverage spec §4.';
